    {
      "label": "“for” + duração",
      "example": "for ten years"
    },
    {
      "label": "“since” + início",
      "example": "since 2015"
    }
  ],
  "drill": [
    {
      "sentence": "I've lived in this apartment ___ six months.",
      "answer": "for",
      "options": [
        "since",
        "for"
      ],
      "feedback": "“For” combina com uma duração, como seis meses."
    },
    {
      "sentence": "Maya has worked at the library ___ 2021.",
      "answer": "since",
      "options": [
        "for",
        "since"
      ],
      "feedback": "“Since” indica o momento em que algo começou."
    },
    {
      "sentence": "We have been friends ___ high school.",
      "answer": "since",
      "options": [
        "since",
        "for"
      ],
      "feedback": "“Since” indica o ponto de início da amizade."
    },
    {
      "sentence": "He has had that car ___ three weeks.",
      "answer": "for",
      "options": [
        "since",
        "for"
      ],
      "feedback": "“For” combina com uma duração, como três semanas."
    },
    {
      "sentence": "The store has been closed ___ noon.",
      "answer": "since",
      "options": [
        "for",
        "since"
      ],
      "feedback": "“Since” indica o momento em que a loja fechou."
    }
  ]
}

