    {
      "sentence": "El café ___ frío.",
      "answer": "está",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use “estar” for a state, such as being cold."
    },
    {
      "sentence": "Mi tía ___ arquitecta.",
      "answer": "es",
      "options": [
        "está",
        "es"
      ],
      "feedback": "Use “ser” for a profession."
    },
    {
      "sentence": "El banco ___ cerca del parque.",
      "answer": "está",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use “estar” to say where something is."
    },
    {
      "sentence": "El bebé ___ dormido.",
      "answer": "está",
      "options": [
        "está",
        "es"
      ],
      "feedback": "Use “estar” for a state, such as being asleep."
    },
    {
      "sentence": "Mi primo ___ músico.",
      "answer": "es",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use “ser” for a person's profession."
    }
  ]
}

