    {
      "sentence": "How ___ emails did you get today?",
      "answer": "many",
      "options": [
        "much",
        "many"
      ],
      "feedback": "Use \"many\" porque você pode contar os e-mails no plural."
    },
    {
      "sentence": "We don't have ___ coffee left.",
      "answer": "much",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"much\" porque o café é tratado como uma quantidade."
    },
    {
      "sentence": "How ___ cousins do you have?",
      "answer": "many",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"many\" porque você pode contar os primos no plural."
    },
    {
      "sentence": "Is there ___ traffic on this road?",
      "answer": "much",
      "options": [
        "much",
        "many"
      ],
      "feedback": "Use \"much\" porque o trânsito é tratado como uma quantidade."
    },
    {
      "sentence": "She doesn't eat ___ rice.",
      "answer": "much",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"much\" porque o arroz é tratado como uma quantidade."
    }
  ]
}

{
  "kind": "pattern",
  "mistakeNumbers": [
    1,
