  ],
  "title": "Contractions with “em”",
  "rule": "In Portuguese, “em” combines with “o” to make “no” and with “a” to make “na.” English does not combine the preposition and article, so you may leave them separate.",
  "contrast": [
    {
      "label": "“em” + “o” becomes “no”",
      "example": "O mercado fica no bairro."
    },
    {
      "label": "“em” + “a” becomes “na”",
      "example": "As chaves estão na gaveta."
    }
  ],
  "drill": [
    {
      "sentence": "A reunião é ___ sala principal.",
      "answer": "na",
      "options": [
        "em a",
        "na"
      ],
      "feedback": "Use “na” because “em” combines with “a.”"
    },
    {
      "sentence": "Meu irmão trabalha ___ banco do centro.",
      "answer": "no",
      "options": [
        "em o",
        "no"
      ],
      "feedback": "Use “no” because “em” combines with “o.”"
    },
    {
      "sentence": "As chaves estão ___ gaveta.",
      "answer": "na",
      "options": [
        "na",
        "em a"
      ],
      "feedback": "Use “na” because “em” combines with “a.”"
    },
    {
      "sentence": "O mercado fica ___ bairro antigo.",
      "answer": "no",
      "options": [
        "no",
        "em o"
      ],
      "feedback": "Use “no” because “em” combines with “o.”"
    },
    {
      "sentence": "A professora está ___ biblioteca agora.",
      "answer": "na",
      "options": [
        "em a",
        "na"
      ],
      "feedback": "Use “na” because “em” combines with “a.”"
    }
  ]
}
